/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_LTlekseru2eToken { dan_hdr h; int64_t len, cap; dt_lekseru2eToken *items; };

static void dl_LTlekseru2eToken_destroy(dan_hdr *h) {
    dl_LTlekseru2eToken *l = (dl_LTlekseru2eToken *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dt_lekseru2eToken_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_LTlekseru2eToken *dl_LTlekseru2eToken_from(int64_t n, dt_lekseru2eToken const *src) {
    dl_LTlekseru2eToken *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_LTlekseru2eToken_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dt_lekseru2eToken));
    for (int64_t i = 0; i < n; i++) l->items[i] = dt_lekseru2eToken_share(src[i]);
    return l;
}

static void dl_LTlekseru2eToken_push(dl_LTlekseru2eToken *l, dt_lekseru2eToken v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dt_lekseru2eToken));
    }
    l->items[l->len++] = dt_lekseru2eToken_share(v);
}

static dt_lekseru2eToken dl_LTlekseru2eToken_get(const dl_LTlekseru2eToken *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dt_lekseru2eToken *dl_LTlekseru2eToken_at(dl_LTlekseru2eToken *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_LTlekseru2eToken_set(dl_LTlekseru2eToken *l, int64_t i, dt_lekseru2eToken v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dt_lekseru2eToken old = l->items[i];
    l->items[i] = dt_lekseru2eToken_share(v);
    dt_lekseru2eToken_release(old);
    (void)old;
}

static void dl_LTlekseru2eToken_write(const dl_LTlekseru2eToken *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dt_lekseru2eToken_write(l->items[i]);
    }
    putchar(']');
}

static void dl_LTlekseru2eToken_insert(dl_LTlekseru2eToken *l, int64_t i, dt_lekseru2eToken v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_LTlekseru2eToken_push(l, v);
    dt_lekseru2eToken last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dt_lekseru2eToken));
    l->items[i] = last;
}

static void dl_LTlekseru2eToken_remove(dl_LTlekseru2eToken *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dt_lekseru2eToken old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dt_lekseru2eToken));
    l->len--;
    dt_lekseru2eToken_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_LTlekseru2eToken *dl_LTlekseru2eToken_copy(const dl_LTlekseru2eToken *l) {
    return dl_LTlekseru2eToken_from(l->len, l->items);
}

static inline dl_LTlekseru2eToken *dl_LTlekseru2eToken_share(dl_LTlekseru2eToken *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LTlekseru2eToken_release(dl_LTlekseru2eToken *l) { if (l) dan_hdr_release(&l->h, dl_LTlekseru2eToken_destroy); }
static inline void dl_LTlekseru2eToken_give(dl_LTlekseru2eToken *l) { if (l) dan_hdr_give(&l->h, dl_LTlekseru2eToken_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LTlekseru2eToken *dl_LTlekseru2eToken_mut(dl_LTlekseru2eToken **pp) {
    dl_LTlekseru2eToken *l = *pp;
    if (l->h.rc > 1) {
        dl_LTlekseru2eToken *r = dl_LTlekseru2eToken_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LTlekseru2eToken *dl_LTlekseru2eToken_reversed(const dl_LTlekseru2eToken *l) {
    dl_LTlekseru2eToken *r = dl_LTlekseru2eToken_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dt_lekseru2eToken t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LTlekseru2eToken *dl_LTlekseru2eToken_slice(const dl_LTlekseru2eToken *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LTlekseru2eToken_from(b - a + 1, l->items + a);
}

static dan_str dl_LTlekseru2eToken_str(const dl_LTlekseru2eToken *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dt_lekseru2eToken_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LTlekseru2eToken_find(const dl_LTlekseru2eToken *l, dt_lekseru2eToken b) {
    for (int64_t i = 0; i < l->len; i++) { dt_lekseru2eToken a = l->items[i]; if (dt_lekseru2eToken_eq(a, b)) return i; }
    return -1;
}
static bool dl_LTlekseru2eToken_contains(const dl_LTlekseru2eToken *l, dt_lekseru2eToken b) { return dl_LTlekseru2eToken_find(l, b) >= 0; }
static bool dl_LTlekseru2eToken_eq(const dl_LTlekseru2eToken *x, const dl_LTlekseru2eToken *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dt_lekseru2eToken a = x->items[i]; dt_lekseru2eToken b = y->items[i]; if (!(dt_lekseru2eToken_eq(a, b))) return false; }
    return true;
}


