    if (d->n == d->cap) dm_DsLTporozhdenieu2ePotreblyaemyj_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dl_LTporozhdenieu2ePotreblyaemyj_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
