/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_DsLTrazboru2eUzel *dm_DsLTrazboru2eUzel_copy(const dm_DsLTrazboru2eUzel *d) {
    dm_DsLTrazboru2eUzel *r = dm_DsLTrazboru2eUzel_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_DsLTrazboru2eUzel_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dl_LTrazboru2eUzel_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_DsLTrazboru2eUzel_reindex(r);
    return r;
}
static dm_DsLTrazboru2eUzel *dm_DsLTrazboru2eUzel_mut(dm_DsLTrazboru2eUzel **pp) {
    dm_DsLTrazboru2eUzel *d = *pp;
    if (d->h.rc > 1) { dm_DsLTrazboru2eUzel *r = dm_DsLTrazboru2eUzel_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
